// global frame -> mouth openness 0..1
export const mouthAt = (frame: number) => MOUTH[Math.max(0, Math.min(MOUTH.length - 1, Math.round(frame)))] ?? 0;
export const vStart = (i: number) => VOICE_CUES[Math.min(i, VOICE_CUES.length - 1)].startFrame;
export const vEnd = (i: number) => VOICE_CUES[Math.min(i, VOICE_CUES.length - 1)].endFrame;
